static void desktop_frame(HWND hwnd,const wchar_t *prefix,const wchar_t *name){RECT r;GetWindowRect(hwnd,&r);int width=r.right-r.left,height=r.bottom-r.top;HDC screen=GetDC(NULL),dc=CreateCompatibleDC(screen);BITMAPINFO info={0};void *bits=NULL;info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=width;info.bmiHeader.biHeight=-height;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;HBITMAP bmp=CreateDIBSection(dc,&info,DIB_RGB_COLORS,&bits,NULL,0);CHECK(bmp&&IsWindowVisible(hwnd));if(bmp){HGDIOBJ old=SelectObject(dc,bmp);CHECK(BitBlt(dc,0,0,width,height,screen,r.left,r.top,SRCCOPY|CAPTUREBLT));GdiFlush();save_bmp(prefix,name,bits,width,height);SelectObject(dc,old);DeleteObject(bmp);}DeleteDC(dc);ReleaseDC(NULL,screen);}
